NEW_FILES = {'migrations/migrate_supermarket_cooler.py': '#!/usr/bin/env python3\n"""\nmigrate_supermarket_cooler.py  --  a supermarket has its cooler wall, and is furnished as a supermarket\n======================================================================================================\nOne-shot, idempotent migration over specs/*.json (0.275.0). The walker, 2026-10-26, walking seed 9205\'s\nsupermarket: "far too dark in teh super market", and the comps after it -- "shiny floor, bright lights, isles,\nglowing freezer section, stacked high" (the factory\'s docs/reference/GROCERY_STORE_COMPS.md: one aisle of glass-door\nreach-in cases lit from inside, brighter than the floor in front of them).\n\nWHY. The library\'s three supermarkets stood no cooler at all. `migrate_cooler_wall.py` gives a convenience store\nits 8 m run on its sales floor, and 0.272.0 kept supermarkets out of that rule on purpose ("their cooler wall and\nglass front are their own decision"). This is that decision: a supermarket\'s cooler wall is the length of its back\nwall, not a corner store\'s ten doors.\n\nTHE RULE, measured per spec rather than authored per spec, on `migrate_cooler_wall`\'s own clearances:\n\n  * the WALL: the sales floor\'s edge opposite its storefront glass -- the back wall the aisles\' heads face, where\n    a real store backs its dairy and frozen cases onto the stockroom -- else the longest other solid edge;\n    `migrate_cooler_wall._edge_walls` reads them, and a glazed wall is never one;\n  * its doors keep `DOOR_CLEAR` either side, and anything AUTHORED in the `AISLE` in front of it cuts the run\n    short. The furnishing is stripped before the plan is made (`level_design.unfurnished`) and laid again after\n    it, so a filing cabinet the old recipe stood there does not decide where the coolers go;\n  * the longest stretch left, at most `RUN` long and centred on it, refused below `MIN_RUN`;\n  * built as runs of at most `PIECE` (Zoo `cooler_run`\'s genome width, 12.0 m), equal lengths, named\n    `cooler_run_sales_<i>` -- every one routes to the species by its `cooler_run` stem.\n\nTHE SPEC IS REFURNISHED AFTER (`migrate_furnish_recipes.migrate`), for the reason `migrate_cooler_wall` gives:\nthe library is a fixed point of its furnishing pass, and the cooler is new input to it. That pass also lays the\nsupermarket\'s own recipe (`level_design._RECIPES["supermarket"]`, 0.275.0) in place of the shop floor\'s.\n\n`lf_*` specs are Level Factory\'s per-run transients and are skipped.\n\n    python migrations/migrate_supermarket_cooler.py            # write specs/\n    python migrations/migrate_supermarket_cooler.py --check    # report only; exit 1 if any\n    python migrations/migrate_supermarket_cooler.py --dir D    # another spec directory\n"""\nimport glob\nimport io\nimport json\nimport math\nimport os\nimport sys\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, HERE)\nsys.path.insert(0, os.path.join(HERE, "migrations"))\n\nimport level_design  # noqa: E402\nimport migrate_cooler_wall as C  # noqa: E402\n\nNAME = "cooler_run_sales"\n#: The longest wall of coolers a supermarket stands: two of Zoo\'s longest runs.\nRUN = 24.0\n#: Zoo `cooler_run`\'s genome width, at most.\nPIECE = 12.0\nMIN_RUN = C.MIN_RUN\n#: A volume whose foot stands higher than this over storey 0\'s floor is not in the cooler\'s aisle: a sign hung over\n#: the floor, or the storey above.\nFOOT_MAX = 2.0\n\n\ndef sales_floor(spec):\n    """The supermarket\'s storey-0 selling floor (`level_design.is_supermarket_floor`), or None."""\n    building = level_design.club_building_id(spec)\n    for r in spec.get("rooms") or []:\n        if int(r.get("story", 0) or 0) == 0 and r.get("bounds") and level_design.is_supermarket_floor(r, building):\n            return r\n    return None\n\n\ndef _in_room(v, b):\n    return b[0] <= v["x"] <= b[2] and b[1] <= v["y"] <= b[3]\n\n\ndef plan(spec):\n    """``(volumes, why)``: the cooler runs this supermarket\'s sales floor should stand, or ``([], why)``.\n    `spec` is the spec as furnish leaves it unfurnished."""\n    room = sales_floor(spec)\n    if room is None:\n        return [], "no storey-0 supermarket sales floor"\n    b = room["bounds"]\n    storefront = {w.get("wall") for w in spec.get("ext_walls") or []\n                  if "glass" in str(w.get("material") or "") and int(w.get("story", 0) or 0) == 0}\n    back_walls = {C._OPPOSITE[w] for w in storefront if w in C._OPPOSITE}\n    best = None\n    for axis, line, lo, hi, sign, ops, ext in C._edge_walls(spec, b):\n        if ext and (ext in storefront or any(k == "window" for _c, _w, k, _m in ops)):\n            continue\n        intervals = [(lo + C.CORNER, hi - C.CORNER)]\n        for c, w, _k, _m in ops:\n            intervals = C._subtract(intervals, c - w / 2.0 - C.DOOR_CLEAR, c + w / 2.0 + C.DOOR_CLEAR)\n        back = line + sign * C.WALL_BACK\n        front = back + sign * C.DEPTH\n        band = sorted((back, front + sign * C.AISLE))\n        for v in spec.get("volumes") or []:\n            # storey 0\'s only: a basement\'s furniture under the wall is not in its aisle\n            foot = float(v.get("z", 0.0)) - float(v.get("size_z", 0.0)) / 2.0\n            if foot < -0.5 or foot > FOOT_MAX:\n                continue\n            vx0, vx1 = v["x"] - v["size_x"] / 2.0, v["x"] + v["size_x"] / 2.0\n            vy0, vy1 = v["y"] - v["size_y"] / 2.0, v["y"] + v["size_y"] / 2.0\n            along = (vx0, vx1) if axis == "X" else (vy0, vy1)\n            across = (vy0, vy1) if axis == "X" else (vx0, vx1)\n            if across[1] <= band[0] + C.EPS or across[0] >= band[1] - C.EPS:\n                continue\n            if v["size_x"] * v["size_y"] > 400.0:\n                continue\n            intervals = C._subtract(intervals, along[0] - 0.05, along[1] + 0.05)\n        side = {("X", -1): "N", ("X", +1): "S", ("Y", -1): "E", ("Y", +1): "W"}[(axis, sign)]\n        for a0, a1 in intervals:\n            if a1 - a0 < MIN_RUN:\n                continue\n            key = (side in back_walls, min(a1 - a0, RUN), a1 - a0)\n            if best is None or key > best[0]:\n                best = (key, a0, a1, axis, back, sign, side)\n    if best is None:\n        return [], "no stretch of a solid sales-floor wall is %.1f m clear" % MIN_RUN\n    _key, a0, a1, axis, back, sign, side = best\n    length = min(a1 - a0, RUN)\n    n = max(1, int(math.ceil(length / PIECE - 1e-9)))\n    each = length / n\n    start = (a0 + a1) / 2.0 - length / 2.0\n    cy = back + sign * C.DEPTH / 2.0\n    have = {m.get("id") for m in spec.get("materials") or []}\n    mat = ("cooler_panel" if "cooler_panel" in have\n           else level_design._declare_material(spec, "metal", level_design._PROP_ACOUSTIC["metal"]))\n    out = []\n    for i in range(n):\n        mid = start + (i + 0.5) * each\n        if axis == "X":\n            vol = {"name": "%s_%d" % (NAME, i), "x": round(mid, 4), "y": round(cy, 4), "z": C.HEIGHT / 2.0,\n                   "size_x": round(each, 3), "size_y": C.DEPTH, "size_z": C.HEIGHT}\n        else:\n            vol = {"name": "%s_%d" % (NAME, i), "x": round(cy, 4), "y": round(mid, 4), "z": C.HEIGHT / 2.0,\n                   "size_x": C.DEPTH, "size_y": round(each, 3), "size_z": C.HEIGHT}\n        vol.update({"collision": "convex", "material": mat})\n        if sign > 0:\n            vol["rot_z"] = 180.0\n        out.append(vol)\n    return out, "the sales floor\'s %s wall, %d run(s) of %.2f m in a %.2f m stretch" % (side, n, each, a1 - a0)\n\n\ndef has_cooler(spec):\n    room = sales_floor(spec)\n    return bool(room) and any(str(v.get("name", "")).startswith("cooler_run") and _in_room(v, room["bounds"])\n                              for v in spec.get("volumes") or [])\n\n\ndef main(argv=None):\n    argv = sys.argv[1:] if argv is None else argv\n    check = "--check" in argv\n    root = os.path.join(HERE, "specs")\n    if "--dir" in argv:\n        root = argv[argv.index("--dir") + 1]\n    placed = refused = 0\n    import migrate_furnish_recipes\n    for p in sorted(glob.glob(os.path.join(root, "*.json"))):\n        if os.path.basename(p).startswith("lf_"):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        if sales_floor(d) is None or has_cooler(d):\n            continue\n        bare = level_design.unfurnished(d)\n        vols, why = plan(bare)\n        if not vols:\n            refused += 1\n            print(f"[supermarket_cooler] {os.path.basename(p)}: REFUSED -- {why}")\n            continue\n        placed += 1\n        print(f"[supermarket_cooler] {os.path.basename(p)}: {why}")\n        if check:\n            continue\n        # a material `plan` declared on the bare copy is declared on the spec\n        d["materials"] = bare.get("materials", d.get("materials"))\n        d["volumes"] = (d.get("volumes") or []) + vols\n        migrate_furnish_recipes.migrate(d)\n        io.open(p, "w", encoding="utf-8", newline="\\n").write(json.dumps(d, indent=1) + "\\n")\n    verb = "need a cooler wall" if check else "given a cooler wall"\n    print(f"[supermarket_cooler] {placed} spec(s) {verb}, {refused} refused")\n    return 1 if check and placed else 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 'tests/test_supermarket_dress.py': '"""A supermarket is furnished as one and stands a cooler wall (0.275.0) -- pure, no bpy.\n\nThe walker, 2026-10-26, walking seed 9205\'s supermarket: "far too dark in teh super market", and the comps after it --\n"shiny floor, bright lights, isles, glowing freezer section, stacked high" (the factory\'s\ndocs/reference/GROCERY_STORE_COMPS.md). The library\'s three supermarkets stood no cooler, their sales floors took the\nshop floor\'s recipe -- filing cabinets, vending, video poker -- and supermarket_a02 had no aisle at all.\n\nFAILS ON 0.274.0: `is_supermarket_floor` does not exist, no supermarket stands a `cooler_run`, and supermarket_a02\'s\nsales floor stands no gondola.\n\nRun:  python -m pytest tests/test_supermarket_dress.py\n"""\nimport json\nimport os\nimport re\nimport sys\n\nimport level_design as L\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, os.path.join(HERE, "migrations"))\nSHELLS = ("supermarket_a01", "supermarket_a02", "supermarket_a03")\n#: What the shop floor\'s recipe stood on a supermarket\'s sales floor and the supermarket\'s does not.\nNOT_A_SUPERMARKET = ("cabinet_file", "vending", "video_poker", "bar_stool", "counter_service", "poster_wall_store")\n\n\ndef _spec(stem):\n    return json.load(open(os.path.join(HERE, "specs", stem + ".json"), encoding="utf-8"))\n\n\ndef _floor(d):\n    return next(r for r in d["rooms"] if r["id"] == "sales_floor")\n\n\ndef _on(d, room):\n    x0, y0, x1, y1 = room["bounds"]\n    return [v for v in d["volumes"] if x0 <= v["x"] <= x1 and y0 <= v["y"] <= y1\n            and -0.5 < v["z"] - v["size_z"] / 2.0 < 2.5]\n\n\ndef test_the_rule_names_a_supermarkets_selling_floor_only():\n    assert L.is_supermarket_floor({"id": "sales_floor"}, "supermarket_a02")\n    for rid in ("mezz_floor", "stockroom", "back_stock", "cash_office", "manager_suite", "receiving"):\n        assert not L.is_supermarket_floor({"id": rid}, "supermarket_a02"), rid\n    assert not L.is_supermarket_floor({"id": "sales_floor"}, "convenience_store_a01")\n    assert L._room_kind({"id": "sales_floor", "story": 0}, "supermarket_a01") == "supermarket"\n    assert L._room_kind({"id": "sales_floor", "story": 0}, "convenience_store_a01") == "shop_floor"\n\n\ndef test_every_supermarket_stands_a_cooler_wall_on_its_back_wall():\n    """Opposite the storefront glass, facing into the sales floor, at least 16 m of it in two runs no longer than\n    Zoo\'s `cooler_run` builds."""\n    for stem in SHELLS:\n        d = _spec(stem)\n        room = _floor(d)\n        coolers = [v for v in _on(d, room) if v["name"].startswith("cooler_run")]\n        assert len(coolers) == 2, (stem, [v["name"] for v in coolers])\n        assert sum(v["size_x"] for v in coolers) >= 16.0, stem\n        for v in coolers:\n            assert v["size_x"] <= 12.0 and v["size_y"] == 0.9, (stem, v)\n            # the N wall, the room on its -y side: unturned, so its doors face -y, into the room\n            assert abs(v["y"] + 0.45 - (room["bounds"][3] - 0.17)) < 1e-3 and "rot_z" not in v, (stem, v)\n\n\ndef test_a_supermarket_floor_is_shelving_not_an_office():\n    for stem in SHELLS:\n        d = _spec(stem)\n        names = [v["name"] for v in _on(d, _floor(d))]\n        assert not [n for n in names if n.startswith(NOT_A_SUPERMARKET)], (stem, names)\n        assert sum(n.startswith("shelf_run") for n in names) >= 8, (stem, names)\n        assert sum(n.startswith("gondola_") for n in names) >= 4, (stem, names)\n\n\ndef test_authored_aisles_take_no_rows_and_a_bare_floor_takes_long_runs():\n    """supermarket_a01\'s five 14 m aisles are its rows; the first build of this recipe laid 3.6 m islands down the\n    lanes between them. supermarket_a02 had none and lays runs of 7.2 m or more, below shelter."""\n    d = _spec("supermarket_a01")\n    assert not [v for v in _on(d, _floor(d)) if v["name"].startswith("gondola_run")]\n    assert len(L.authored_aisles(d, _floor(d))) == 5\n    d = _spec("supermarket_a02")\n    runs = [v for v in _on(d, _floor(d)) if v["name"].startswith("gondola_run")]\n    assert len(runs) >= 6, len(runs)\n    for v in runs:\n        assert max(v["size_x"], v["size_y"]) >= 7.2 and v["size_z"] < L.shelter_height(), v\n\n\ndef test_the_migration_is_done_and_idempotent(tmp_path):\n    import migrate_supermarket_cooler as M\n    for stem in SHELLS:\n        (tmp_path / (stem + ".json")).write_text(json.dumps(_spec(stem)), encoding="utf-8")\n    assert M.main(["--check", "--dir", str(tmp_path)]) == 0\n\n\ndef test_every_name_routes():\n    import prop_species\n    assert prop_species.species_for_name("gondola_run_r48016798_14") == "snack_gondola"\n    assert prop_species.species_for_name("cooler_run_sales_0") == "cooler_run"\n'}
CHANGELOG = '## [0.275.0] - a supermarket is furnished as one, and stands its cooler wall\n\nThe walker, 2026-10-26, walking seed 9205\'s supermarket: "far too dark in teh super market". Then came the comps:\n"shiny floor, bright lights, isles, glowing freezer section, stacked high". They are filed as the factory\'s\ndocs/reference/GROCERY_STORE_COMPS.md.\n\nBefore this release:\n- none of the library\'s three supermarkets stood a cooler. 0.272.0 kept them out of the convenience store\'s rule:\n  "their cooler wall and glass front are their own decision";\n- their sales floors took the shop floor\'s recipe. supermarket_a01\'s stood a service counter, two filing cabinets,\n  two vending machines, two video poker machines with their stools, and eleven cartons and bins round its five aisles;\n- supermarket_a02 had no aisle at all.\n\n### Added\n- **`migrations/migrate_supermarket_cooler.py`**: a supermarket\'s sales floor stands a glass-door cooler wall,\n  using `migrate_cooler_wall`\'s clearances.\n  - The wall is the one opposite the storefront glass, where the aisles\' heads face and a real store backs its\n    dairy and frozen cases onto the stockroom.\n  - The run is up to 24 m, in runs of at most 12 m (Zoo `cooler_run`\'s widest), named `cooler_run_sales_<i>`.\n  - It is planned on the spec less its furnishing, then the spec is refurnished.\n  - a01 stands 2 x 8.85 m, a02 2 x 12.00 m, a03 2 x 10.95 m.\n- **The `supermarket` kind** (`level_design.is_supermarket_floor`, `_RECIPES["supermarket"]`). A building whose id\n  says supermarket or grocer, and a room whose id says it sells, are furnished as a supermarket:\n  - its aisles;\n  - shelving stacked along its walls;\n  - one cluster of cartons;\n  - an ATM.\n\n  Its stockroom, mezzanine and offices keep their kinds.\n- **`gondola_run`**: the supermarket\'s rows, Zoo\'s `snack_gondola` at 7.2 to 12.0 m, below shelter like\n  `gondola_aisle`.\n  - A floor whose own aisles already stand (`authored_aisles`) takes no rows. The first build laid 3.6 m islands down\n    the lanes between supermarket_a01\'s 14 m aisles.\n  - supermarket_a02 now stands four rows of three 7.2 m runs.\n\n### Changed\n- A one-cluster recipe lays its rows after its wall run, as every other recipe does. The supermarket is the first\n  one-cluster recipe that has rows.\n- No aisle signs yet. A fixture hangs where a hung slot is free, and the first build hung one over the checkout. A\n  supermarket\'s sign hangs over its aisle, which is a rule of its own.\n\n### Tests\n- `tests/test_supermarket_dress.py` (fails on 0.274.0) checks:\n  - the rule\'s rooms;\n  - every supermarket\'s cooler wall: on the back wall, facing in, at least 16 m;\n  - no office furniture on the floor;\n  - authored aisles take no rows, and a bare floor takes long runs;\n  - the migration is done and idempotent;\n  - the names route.\n- `test_furnish` knows the supermarket\'s rows.\n- `test_card_shop` and `test_store_atms` named a supermarket\'s sales floor a shop floor. It is its own kind now,\n  still never the card shop\'s, and it still sells.\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.274.0', 'Deli Counter 0.275.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
